 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; fn should_process_crate (crate_path : & Path , verbose : bool) -> Result < bool > { let cargo_toml_path = crate_path . join ("Cargo.toml") ; let cargo_toml_content = fs :: read_to_string (& cargo_toml_path) . context (format ! ("Failed to read Cargo.toml from {}" , cargo_toml_path . display ())) ? ; # [derive (Debug , serde :: Deserialize)] struct MinimalCargoToml { package : Option < toml :: Table > , } let minimal_cargo_toml : MinimalCargoToml = toml :: from_str (& cargo_toml_content) . context (format ! ("Failed to parse Cargo.toml from {}" , cargo_toml_path . display ())) ? ; if minimal_cargo_toml . package . is_none () { if verbose { println ! ("Skipping virtual manifest: {}" , cargo_toml_path . display ()) ; } return Ok (false) ; } let crate_name = crate_path . file_name () . and_then (| s | s . to_str ()) . context ("Could not get crate name") ? ; if crate_name == "split-decls-rs" { if verbose { println ! ("Skipping self crate: split-decls-rs") ; } return Ok (false) ; } let lib_rs = crate_path . join ("src/lib.rs") ; if ! lib_rs . exists () { if verbose { println ! ("Skipping crate without lib.rs: {}" , crate_name) ; } return Ok (false) ; } Ok (true) }